// I-17 E2E: the microphone source in the offscreen document, with Chromium's
// fake capture device fed by a synthetic WAV (tests/fixtures/voice-a.wav,
// generated by scripts/fixtures: AGENTS.md R16). No --use-fake-ui-for-media-stream:
// it would grant the offscreen's own request and hide the question I-17 asks.
// The grant is given with CDP Browser.grantPermissions on the extension's
// origin, standing in for «Consenti» in permission.html; the real prompt and
// the recording indicator are manual (tests/e2e/MANUAL_CHECKLIST.md, M13–M14).
// Requires `pnpm build` first.
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { expect, test, type Page } from '@playwright/test';
import { DESCRIPTOR_KEYS } from '@voicecrystal/contracts';
import { decodeWav } from '../../scripts/fixtures/wav.ts';
import { analyzeDescriptors } from '../../extension/src/shared/descriptor-analysis.ts';
import { loadFvad } from '../benchmarks/fvad-loader.ts';
import { ExtensionHarness, OTHER_URL } from './harness.ts';

const FAKE_MIC_WAV = resolve(import.meta.dirname, '../fixtures/voice-a.wav');

const h = new ExtensionHarness();
let panelTab: Page;

test.describe.configure({ mode: 'serial' });

test.beforeAll(async () => {
  await h.launch({
    args: ['--use-fake-device-for-media-stream', `--use-file-for-fake-audio-capture=${FAKE_MIC_WAV}`],
  });
  // The panel opens from the toolbar on any tab; off YouTube it offers the microphone (SPEC §5).
  panelTab = await h.context.newPage();
  await panelTab.goto(OTHER_URL);
  await h.clickAction(panelTab);
  await expect.poll(() => h.inSidePanel(exists('capture-use-mic'))).toBe(true);
});

test.afterAll(async () => {
  await h.close();
});

const exists = (testId: string): string => `document.querySelector('[data-testid="${testId}"]') !== null`;
const click = (testId: string): string =>
  `(() => { const el = document.querySelector('[data-testid="${testId}"]'); if (el === null) return false; el.click(); return true; })()`;
const text = (testId: string): string => `document.querySelector('[data-testid="${testId}"]')?.textContent ?? ''`;
const PANEL_MIC_STATE = `navigator.permissions.query({ name: 'microphone' }).then((s) => s.state)`;

/**
 * Starts a microphone session from the probe page as the panel would, port
 * included, so that only the microphone decides the outcome.
 */
async function startMicFromProbe(): Promise<string> {
  return h.probe.evaluate(async () => {
    const id = crypto.randomUUID();
    const g = globalThis as unknown as { vcPorts?: chrome.runtime.Port[] };
    const onDiag = (message: unknown): boolean => {
      const m = message as { type?: unknown; sessionId?: unknown };
      if (m.type === 'CAPTURE_DIAG' && m.sessionId === id) {
        chrome.runtime.onMessage.removeListener(onDiag);
        (g.vcPorts ??= []).push(chrome.runtime.connect({ name: `vc-panel:${id}` }));
      }
      return false;
    };
    chrome.runtime.onMessage.addListener(onDiag);
    await chrome.runtime
      .sendMessage({ v: 1, type: 'CAPTURE_START', source: 'mic', tabId: null, sessionId: id, seq: 0 })
      .catch(() => undefined);
    return id;
  });
}

async function expectReleased(): Promise<void> {
  await expect.poll(() => h.offscreenCount()).toBe(0);
  await expect.poll(() => h.storage('activeSession')).toBeUndefined();
}

test('without a grant the panel asks for permission.html and the offscreen reports MIC_PERMISSION_REQUIRED', async () => {
  const before = await h.inSidePanel(PANEL_MIC_STATE);
  test.info().annotations.push({ type: 'panel permission before grant', description: String(before) });
  expect(before).not.toBe('granted');

  expect(await h.inSidePanel(click('capture-use-mic'))).toBe(true);
  await expect.poll(() => h.inSidePanel(text('capture-error'))).toContain('autorizzazione al microfono');
  expect(await h.offscreenCount()).toBe(0);
  expect(await h.storage('activeSession')).toBeUndefined();

  // The panel opens the permission page in a tab (no new permission: chrome.tabs.create).
  const opened = h.context.waitForEvent('page');
  expect(await h.inSidePanel(click('capture-open-permission'))).toBe(true);
  const permissionPage = await opened;
  await permissionPage.waitForLoadState();
  expect(permissionPage.url()).toBe(`chrome-extension://${h.extensionId}/permission.html`);
  await expect(permissionPage.getByTestId('permission-allow')).toBeVisible();
  // A refusal (CDP Browser.setPermission stands in for «Blocca»): the page explains how to undo it.
  await h.setMic('denied');
  await permissionPage.getByTestId('permission-allow').click();
  await expect(permissionPage.getByTestId('permission-status')).toHaveAttribute('data-outcome', 'denied');
  await expect(permissionPage.getByTestId('permission-status')).toContainText('non è autorizzato');
  await h.resetPermissions();
  await permissionPage.close();

  // A start that skips the panel's check: the offscreen itself must refuse.
  const sessionId = await startMicFromProbe();
  const end = await h.waitForEnd(sessionId, 20_000);
  test.info().annotations.push({
    type: 'offscreen without grant',
    description: JSON.stringify({ state: end.state, exitReason: end.exitReason, code: end.code, elapsedMs: Math.round(end.elapsedMs) }),
  });
  expect(end).toMatchObject({ state: 'ERROR', code: 'MIC_PERMISSION_REQUIRED' });
  await expectReleased();
});

// No pass-through is a property of the graph (no connection to destination),
// not observable here: checked by listening in M13.
test('with the grant the offscreen opens the microphone, counts samples and stops', async () => {
  await h.grantMic();
  await expect.poll(() => h.inSidePanel(PANEL_MIC_STATE)).toBe('granted');
  // The grant clears the request in the open panel.
  await expect.poll(() => h.inSidePanel(exists('capture-open-permission'))).toBe(false);

  const seen = await h.seenSessions();
  expect(await h.inSidePanel(click('capture-use-mic'))).toBe(true);
  const first = await h.waitForSession('LISTENING', seen);
  expect(first.sampleRate).toBeGreaterThan(0);
  expect(await h.offscreenCount()).toBe(1);

  // Routing state: a microphone session has no tab id at all.
  const active = await h.storage('activeSession');
  expect(active).toEqual({ sessionId: first.sessionId, source: 'mic' });
  expect(await h.storage('lastStart')).toEqual({ sessionId: first.sessionId, source: 'mic', failure: null });
  await expect.poll(() => h.inSidePanel(`document.querySelector('[data-testid="capture-status"]')?.dataset.source`)).toBe('mic');

  // The worklet receives the fake device at about the sample rate.
  const before = (await h.lastDiag()) ?? first;
  await panelTab.waitForTimeout(4_000);
  const later = await h.lastDiag();
  if (later === undefined || first.sampleRate === null) throw new Error('no diagnostics');
  const rate = (later.samples - before.samples) / ((later.at - before.at) / 1000);
  test.info().annotations.push({
    type: 'microphone',
    description: JSON.stringify({ sampleRate: later.sampleRate, samplesPerSecond: Math.round(rate) }),
  });
  expect(later).toMatchObject({ sessionId: first.sessionId, state: 'LISTENING' });
  expect(rate).toBeGreaterThan(first.sampleRate * 0.6);
  expect(rate).toBeLessThan(first.sampleRate * 1.4);
  // Past the 3 s panel-attach deadline: the panel's port is holding it.
  expect(later.elapsedMs).toBeGreaterThan(4_000);

  expect(await h.inSidePanel(click('capture-stop'))).toBe(true);
  const end = await h.waitForEnd(first.sessionId);
  expect(end).toMatchObject({ state: 'INTERRUPTED', exitReason: 'USER_STOP' });
  await expectReleased();
});

test('closing the side panel stops the microphone session within 1 s', async () => {
  await expect.poll(() => h.inSidePanel(exists('capture-use-mic'))).toBe(true);
  const seen = await h.seenSessions();
  expect(await h.inSidePanel(click('capture-use-mic'))).toBe(true);
  const first = await h.waitForSession('LISTENING', seen);
  await panelTab.waitForTimeout(1_000);

  const closedAt = Date.now();
  expect(await h.closeSidePanels()).toBeGreaterThan(0);
  const end = await h.waitForEnd(first.sessionId);
  test.info().annotations.push({ type: 'panel closed → final diagnostic', description: `${end.at - closedAt} ms` });
  expect(end).toMatchObject({ state: 'INTERRUPTED', exitReason: 'USER_STOP' });
  expect(end.at - closedAt).toBeLessThan(1_000);
  await expectReleased();
});

/** Reopens the side panel from the toolbar on the non-YouTube tab. */
async function openPanel(): Promise<void> {
  await h.clickAction(panelTab);
  await expect.poll(() => h.inSidePanel(exists('capture-use-mic'))).toBe(true);
}

/** Starts the microphone from the panel and waits until it listens. */
async function micListening(): Promise<string> {
  const seen = await h.seenSessions();
  expect(await h.inSidePanel(click('capture-use-mic'))).toBe(true);
  return (await h.waitForSession('LISTENING', seen)).sessionId;
}

test('one capture across sources: a mic start during a tab capture gets CAPTURE_BUSY, and the other way round', async () => {
  await openPanel();
  const watch = await h.openWatch();

  // Tab first: the microphone is refused, the tab session is untouched.
  const seen = await h.seenSessions();
  await h.clickAction(watch);
  const tab = await h.waitForSession('LISTENING', seen);
  // While a capture runs the panel offers no microphone button: start as the panel would.
  expect(await h.inSidePanel(exists('capture-use-mic'))).toBe(false);
  const refused = await startMicFromProbe();
  await expect.poll(async () => (await h.storage('lastStart'))?.['failure']).toBe('CAPTURE_BUSY');
  expect(await h.storage('lastStart')).toMatchObject({ sessionId: refused, source: 'mic' });
  expect(await h.offscreenCount()).toBe(1);
  expect(await h.storage('activeSession')).toMatchObject({ sessionId: tab.sessionId, source: 'tab' });
  // The panel offers to stop the running session, which ends the tab capture.
  await expect.poll(() => h.inSidePanel(click('capture-stop-active'))).toBe(true);
  expect(await h.waitForEnd(tab.sessionId)).toMatchObject({ state: 'INTERRUPTED', exitReason: 'USER_STOP' });
  await expectReleased();

  // Microphone first: the toolbar click is refused, the mic session is untouched.
  const mic = await micListening();
  await h.clickAction(watch);
  await expect.poll(async () => (await h.storage('lastStart'))?.['failure']).toBe('CAPTURE_BUSY');
  expect(await h.storage('lastStart')).toMatchObject({ source: 'tab' });
  expect(await h.storage('activeSession')).toEqual({ sessionId: mic, source: 'mic' });
  expect(await h.offscreenCount()).toBe(1);
  await panelTab.waitForTimeout(1_000);
  expect((await h.diags()).filter((d) => d.sessionId === mic).at(-1)?.state).toBe('LISTENING');
  await expect.poll(() => h.inSidePanel(click('capture-stop-active'))).toBe(true);
  expect(await h.waitForEnd(mic)).toMatchObject({ state: 'INTERRUPTED', exitReason: 'USER_STOP' });
  await expectReleased();
  await watch.close();
});

test('S8 with the microphone: the service worker is terminated, the session goes on and stops', async () => {
  await openPanel();
  const mic = await micListening();
  await h.restartServiceWorker();
  const before = await h.lastDiag();
  await panelTab.waitForTimeout(2_000);
  const after = await h.lastDiag();
  expect(after).toMatchObject({ sessionId: mic, state: 'LISTENING' });
  expect((after?.samples ?? 0) - (before?.samples ?? 0)).toBeGreaterThan(0);
  // The stop goes through the new worker instance.
  expect(await h.inSidePanel(click('capture-stop'))).toBe(true);
  expect(await h.waitForEnd(mic)).toMatchObject({ state: 'INTERRUPTED', exitReason: 'USER_STOP' });
  await expectReleased();
  // And a new start works with the woken worker.
  const next = await micListening();
  expect(await h.inSidePanel(click('capture-stop'))).toBe(true);
  expect(await h.waitForEnd(next)).toMatchObject({ state: 'INTERRUPTED', exitReason: 'USER_STOP' });
  await expectReleased();
});

test('a double click on «Usa il microfono» starts one session, which survives past the attach deadline (review M-1)', async () => {
  await openPanel();
  const seen = await h.seenSessions();
  const clicks = await h.inSidePanel(
    `(() => { const b = document.querySelector('[data-testid="capture-use-mic"]'); if (b === null) return 0; b.click();
      const again = document.querySelector('[data-testid="capture-use-mic"]'); if (again !== null) again.click(); return again === null ? 1 : 2; })()`,
  );
  test.info().annotations.push({ type: 'clicks delivered', description: String(clicks) });
  const mic = (await h.waitForSession('LISTENING', seen)).sessionId;
  await panelTab.waitForTimeout(4_000);
  const sessions = (await h.diags()).filter((d) => !seen.includes(d.sessionId));
  expect(new Set(sessions.map((d) => d.sessionId))).toEqual(new Set([mic]));
  expect(sessions.at(-1)).toMatchObject({ sessionId: mic, state: 'LISTENING' });
  expect((await h.storage('lastStart'))?.['failure']).toBeNull();
  expect(await h.inSidePanel(click('capture-stop'))).toBe(true);
  expect(await h.waitForEnd(mic)).toMatchObject({ state: 'INTERRUPTED', exitReason: 'USER_STOP' });
  await expectReleased();
});

test('an offscreen that disappears mid-session leaves a way out: «Usa il microfono» returns and starts (review M-2)', async () => {
  await openPanel();
  const gone = await micListening();
  // Unexpected close: no final diagnostic, the routing state stays behind.
  const worker = await h.worker();
  await worker.evaluate(() => chrome.offscreen.closeDocument());
  await expect.poll(() => h.offscreenCount()).toBe(0);
  expect(await h.storage('activeSession')).toMatchObject({ sessionId: gone, source: 'mic' });
  await expect.poll(() => h.inSidePanel(exists('capture-use-mic')), { timeout: 10_000 }).toBe(true);
  const next = await micListening();
  expect(next).not.toBe(gone);
  expect(await h.storage('activeSession')).toEqual({ sessionId: next, source: 'mic' });
  expect(await h.inSidePanel(click('capture-stop'))).toBe(true);
  expect(await h.waitForEnd(next)).toMatchObject({ state: 'INTERRUPTED', exitReason: 'USER_STOP' });
  await expectReleased();
});

test('microphone listening on the synthetic voice stops at 18 s of valid speech (or earlier, split-half) with a seed close to Node (I-06b, I-07)', async () => {
  test.setTimeout(120_000);
  await openPanel();
  const mic = await micListening();
  // The technical rows grow while listening (I-07).
  await expect.poll(() => h.inSidePanel(text('capture-stability')), { timeout: 40_000 }).toMatch(/s = /);
  // I-13a: the listening screen, with the germ drawn from the provisional seed.
  await expect.poll(() => h.inSidePanel(`document.querySelector('[data-testid="shell-screen"]')?.dataset.screen ?? ''`)).toBe('LIVE');
  await expect.poll(() => h.inSidePanel(`document.querySelector('[data-testid="shell-germ"] svg') !== null`), { timeout: 20_000 }).toBe(true);
  // I-13b: no serious accessibility violation on the listening screen (axe-core).
  expect(await h.axeSidePanel()).toEqual([]);
  // Review H-2: «Interrompi» keeps the focus across the progress ticks (it is updated in place, not rebuilt).
  expect(await h.inSidePanel(`(() => { const b = document.querySelector('[data-testid="shell-stop"]'); b?.focus(); return document.activeElement === b; })()`)).toBe(true);
  await new Promise((r) => setTimeout(r, 1_600));
  expect(await h.inSidePanel(`document.activeElement?.dataset?.testid ?? ''`)).toBe('shell-stop');
  const end = await h.waitForEnd(mic, 90_000);
  // voice-a looped: the split-half halves stay apart (measured in Node, D-AE), so 18 s of valid speech is expected;
  // CONVERGED is accepted too (the browser chain is not bit-exact).
  expect(end.state).toBe('RESULT_READY');
  expect(['MAX_VALID_SPEECH', 'CONVERGED']).toContain(end.exitReason);
  if (end.exitReason === 'MAX_VALID_SPEECH') expect(end.validSpeechMs).toBeGreaterThanOrEqual(18_000);
  expect(end.activeMs).toBeLessThan(45_000);
  expect(end.stability?.evaluations ?? 0).toBeGreaterThan(0);
  const analysis = end.analysis;
  expect(analysis?.failure).toBeNull();
  expect(analysis?.extractorVersion).toBe('extractor-0-experimental');
  expect(analysis?.seed).toHaveLength(6);
  expect(analysis?.quality?.droppedFrames).toBe(0);
  // Review H-2: the worker kept as much audio as the session listened (sample clock), within 1 s.
  expect(Math.abs((analysis?.analysedMs ?? Number.NaN) - end.activeMs)).toBeLessThan(1_000);
  expect(analysis?.quality?.warnings).not.toContain('MIXED_AUDIO_UNCERTAIN');
  expect(analysis?.quality?.warnings).not.toContain('MULTI_SPEAKER_SUSPECTED');
  // The panel shows the seed (technical rows, I-06b).
  await expect.poll(() => h.inSidePanel(text('capture-analysis-seed'))).toBe((analysis?.seed ?? []).join(' · '));
  // Node reference: the same WAV the fake device loops, cut to the audio the worker analysed. The
  // browser's capture chain is not bit-exact and the loop phase is unknown:
  // the distance is measured and recorded, not required to be zero.
  const wav = decodeWav(readFileSync(FAKE_MIC_WAV));
  const one = wav.channels[0] ?? new Float32Array();
  const looped = new Float32Array(one.length * 4);
  for (let k = 0; k < 4; k++) looped.set(one, k * one.length);
  const keep = Math.min(looped.length, Math.round(((analysis?.analysedMs ?? 0) * wav.sampleRate) / 1000));
  const node = await analyzeDescriptors([looped.subarray(0, keep)], wav.sampleRate, loadFvad().fvad);
  expect(node.status).toBe('OK');
  const panelSeed = analysis?.seed ?? null;
  const nodeSeed = node.seed;
  if (panelSeed === null || nodeSeed === null) throw new Error('both seeds are required here');
  const deltas = DESCRIPTOR_KEYS.map((_key, i) => Math.abs(((panelSeed[i] ?? Number.NaN) - (nodeSeed[i] ?? Number.NaN)) / 100));
  // Time of the end-of-session analysis in the offscreen worker: FINALIZING → final diagnostic, at the probe page.
  const diags = (await h.diags()).filter((d) => d.sessionId === mic);
  const finalizing = diags.find((d) => d.state === 'FINALIZING')?.at ?? null;
  const analysisMs = finalizing === null ? null : end.at - finalizing;
  // I-07: the split-half evaluations while listening (their time in the worker, the s_t of each).
  const evaluations = diags.filter((d) => d.stability !== null && d.stability.analysisMs !== null);
  const evaluationMs = evaluations.map((d) => d.stability?.analysisMs ?? 0);
  const measured = {
    exitReason: end.exitReason,
    panelSeed: analysis?.seed,
    nodeSeed: node.seed,
    deltaPoints: deltas,
    validSpeechMs: analysis?.quality?.validSpeechMs,
    liveValidSpeechMs: end.validSpeechMs,
    warnings: analysis?.quality?.warnings,
    analysisMs,
    analysedMs: analysis?.analysedMs ?? null,
    activeMs: end.activeMs,
    stability: end.stability,
    evaluationMsMax: evaluationMs.length > 0 ? Math.max(...evaluationMs) : null,
  };
  test.info().annotations.push({ type: 'mic seed vs Node (points)', description: JSON.stringify(measured) });
  writeFileSync(resolve(import.meta.dirname, '../../test-results/i07-mic-stop.json'), JSON.stringify(measured, null, 2));
  // p1 depends only on the voice f0 (120 Hz): it must match. The others depend on where the loop starts
  // of the fake device; measured on 2026-11-12 (BENCHMARK_PROTOCOL §7) on 45 s: 0.01–0.9 points, p6 8.7 once.
  expect(deltas[0]).toBeLessThan(2);
  await expectReleased();
});
